board.js:
```js
(function (global) {
  'use strict';
  const T = global.Tetris = global.Tetris || {};
  const { COLS, ROWS } = T.constants;

  function create() {
    return Array.from({ length: ROWS }, () => Array(COLS).fill(null));
  }

  // 检测 piece 在 board 上是否合法（边界 + 重叠）
  function valid(board, piece) {
    const cells = pieceCells(piece);
    for (const c of cells) {
      if (c.x < 0 || c.x >= COLS || c.y >= ROWS) return false;
      if (c.y < 0) continue; // 顶部上方允许
      if (board[c.y][c.x] !== null) return false;
    }
    return true;
  }

  function pieceCells(piece) {
    const cells = [];
    const m = piece.matrix;
    for (let r = 0; r < m.length; r++) {
      for (let c = 0; c < m[r].length; c++) {
        if (m[r][c]) cells.push({ x: piece.x + c, y: piece.y + r });
      }
    }
    return cells;
  }

  function merge(board, piece) {
    for (const c of pieceCells(piece)) {
      if (c.y >= 0) board[c.y][c.x] = piece.color;
    }
  }

  function clearLines(board) {
    let cleared = 0;
    for (let r = ROWS - 1; r >= 0; r--) {
      if (board[r].every(cell => cell !== null)) {
        board.splice(r, 1);
        board.unshift(Array(COLS).fill(null));
        cleared++;
        r++; // 重新检查同一行
      }
    }
    return cleared;
  }

  T.board = { create, valid, merge, clearLines, pieceCells };
})(window);
```

piece.js:
```js
(function (global) {
  'use strict';
  const T = global.Tetris = global.Tetris || {};
  const { COLS, COLORS, SHAPES } = T.constants;

  function randomType() {
    const types = Object.keys(SHAPES);
    return types[Math.floor(Math.random() * types.length)];
  }

  function create(type) {
    type = type || randomType();
    const matrix = SHAPES[type].map(row => row.slice());
    return {
      type,
      color: COLORS[type],
      matrix,
      x: Math.floor((COLS - matrix[0].length) / 2),
      y: 0,
    };
  }

  function rotateMatrix(m) {
    const n = m.length;
    const res = Array.from({ length: n }, () => Array(n).fill(0));
    for (let r = 0; r < n; r++)
      for (let c = 0; c < n; c++)
        res[c][n - 1 - r] = m[r][c];
    return res;
  }

  function rotate(piece, board) {
    const rotated = rotateMatrix(piece.matrix);
    // 尝试墙踢：原始位置及左右偏移
    const attempts = [0, -1, 1, -2, 2];
    for (const dx of attempts) {
      const candidate = { ...piece, matrix: rotated, x: piece.x + dx };
      if (T.board.valid(board, candidate)) {
        piece.matrix = rotated;
        piece.x += dx;
        return true;
      }
    }
    return false;
  }

  function move(piece, board, dx, dy) {
    const candidate = { ...piece, x: piece.x + dx, y: piece.y + dy };
    if (T.board.valid(board, candidate)) {
      piece.x += dx;
      piece.y += dy;
      return true;
    }
    return false;
  }

  function drop(piece, board) {
    let dist = 0;
    while (move(piece, board, 0, 1)) dist++;
    return dist;
  }

  T.piece = { create, rotate, move, drop, randomType };
})(window);
```

