{"filepath": "/mnt/d/project/coding/tetris/js/board.js", "content": "/**
 * board.js —— 棋盘状态管理（模块 2）
 * 负责棋盘创建、碰撞检测、方块固定、消行。
 */
(function (global) {
  'use strict';
  const T = (global.Tetris = global.Tetris || {});
  const { COLS, ROWS } = T.constants;

  // 创建空棋盘：ROWS 行 × COLS 列，每格 null 表示空，否则存颜色
  function create() {
    return Array.from({ length: ROWS }, () => Array(COLS).fill(null));
  }

  // 提取方块占据的所有格子坐标（相对棋盘）
  function pieceCells(piece) {
    const cells = [];
    const m = piece.matrix;
    for (let r = 0; r < m.length; r++) {
      for (let c = 0; c < m[r].length; c++) {
        if (m[r][c]) cells.push({ x: piece.x + c, y: piece.y + r });
      }
    }
    return cells;
  }

  // 判断方块在棋盘上是否合法（不越界、不重叠）
  function valid(board, piece) {
    for (const cell of pieceCells(piece)) {
      if (cell.x < 0 || cell.x >= COLS || cell.y >= ROWS) return false;
      if (cell.y < 0) continue; // 允许在顶面上方
      if (board[cell.y][cell.x] !== null) return false;
    }
    return true;
  }

  // 将方块固定到棋盘
  function merge(board, piece) {
    for (const cell of pieceCells(piece)) {
      if (cell.y >= 0) board[cell.y][cell.x] = piece.color;
    }
  }

  // 消除满行，返回消除的行数
  function clearLines(board) {
    let cleared = 0;
    for (let r = ROWS - 1; r >= 0; r--) {
      if (board[r].every((cell) => cell !== null)) {
        board.splice(r, 1);
        board.unshift(Array(COLS).fill(null));
        cleared++;
        r++; // 上方行下沉后重新检查同一索引
      }
    }
    return cleared;
  }

  T.board = { create, pieceCells, valid, merge, clearLines };
})(window);
"}

{"filepath": "/mnt/d/project/coding/tetris/js/piece.js", "content": "/**
 * piece.js —— 活动方块逻辑（模块 3）
 * 负责方块生成、旋转（含墙踢）、移动、硬降。
 */
(function (global) {
  'use strict';
  const T = (global.Tetris = global.Tetris || {});
  const { COLS, COLORS, SHAPES } = T.constants;

  function randomType() {
    const types = Object.keys(SHAPES);
    return types[Math.floor(Math.random() * types.length)];
  }

  // 创建一个新方块（可选指定类型）
  function create(type) {
    type = type || randomType();
    const matrix = SHAPES[type].map((row) => row.slice()); // 深拷贝
    return {
      type,
      color: COLORS[type],
      matrix,
      x: Math.floor((COLS - matrix[0].length) / 2), // 水平居中
      y: 0,
    };
  }

  // 矩阵顺时针旋转 90°
  function rotateMatrix(m) {
    const n = m.length;
    const res = Array.from({ length: n }, () => Array(n).fill(0));
    for (let r = 0; r < n; r++) {
      for (let c = 0; c < n; c++) {
        res[c][n - 1 - r] = m[r][c];
      }
    }
    return res;
  }

  // 顺时针旋转，带简单墙踢（依次尝试左右偏移）
  function rotate(piece, board) {
    const rotated = rotateMatrix(piece.matrix);
    const kicks = [0, -1, 1, -2, 2];
    for (const dx of kicks) {
      const candidate = { ...piece, matrix: rotated, x: piece.x + dx };
      if (T.board.valid(board, candidate)) {
        piece.matrix = rotated;
        piece.x += dx;
        return true;
      }
    }
    return false;
  }

  // 逆时针旋转（等于顺时针 3 次），同样带墙踢
  function rotateCCW(piece, board) {
    for (let i = 0; i < 3; i++) {
      if (!rotate(piece, board)) return false;
    }
    return true;
  }

  // 平移；成功返回 true
  function move(piece, board, dx, dy) {
    const candidate = { ...piece, x: piece.x + dx, y: piece.y + dy };
    if (T.board.valid(board, candidate)) {
      piece.x += dx;
      piece.y += dy;
      return true;
    }
    return false;
  }

  // 硬降：直接落到底，返回下落格数
  function drop(piece, board) {
    let dist = 0;
    while (move(piece, board, 0, 1)) dist++;
    return dist;
  }

  T.piece = { create, rotate, rotateCCW, move, drop, randomType };
})(window);
"}

{"filepath": "/mnt/d/project/coding/tetris/js/renderer.js", "content": "/**
 * renderer.js —— Canvas 渲染（模块 4）
 * 负责绘制棋盘、已堆叠方块、幽灵投影、当前方块与下一方块预览。
 */
(function (global) {
  'use strict';
  const T = (global.Tetris = global.Tetris || {});
  const { COLS, ROWS, CELL } = T.constants;

  let ctx, nextCtx;

  function init(boardCanvasId, nextCanvasId) {
    const board = document.getElementById(boardCanvasId);
    const next = document.getElementById(nextCanvasId);
    ctx = board.getContext('2d');
    nextCtx = next.getContext('2d');
  }

  // 绘制单个带立体感的方块
  function drawBlock(context, px, py, size, color, ghost) {
    if (ghost) {
      context.fillStyle = 'rgba(255,255,255,0.06)';
      context.fillRect(px, py, size, size);
      context.strokeStyle = color;
      context.globalAlpha = 0.5;
      context.lineWidth = 1.5;
      context.strokeRect(px + 0.75, py + 0.75, size - 1.5, size - 1.5);
      context.globalAlpha = 1;
      return;
    }
    const s = size - 1;
    context.fillStyle = color;
    context.fillRect(px, py, s, s);
    // 高光（上左）
    context.fillStyle = 'rgba(255,255,255,0.35)';
    context.fillRect(px, py, s, 3);
    context.fillRect(px, py, 3, s);
    // 阴影（下右）
    context.fillStyle = 'rgba(0,0,0,0.3)';
    context.fillRect(px, py + s - 3, s, 3);
    context.fillRect(px + s - 3, py, 3, s);
  }

  function drawGrid() {
    ctx.clearRect(0, 0, COLS * CELL, ROWS * CELL);
    ctx.strokeStyle = 'rgba(255,255,255,0.045)';
    ctx.lineWidth = 1;
    for (let c = 1; c < COLS; c++) {
      const x = c * CELL;
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, ROWS * CELL); ctx.stroke();
    }
    for (let r = 1; r < ROWS; r++) {
      const y = r * CELL;
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(COLS * CELL, y); ctx.stroke();
    }
  }

  // 计算幽灵投影位置（当前方块能下落到的最远位置）
  function ghostY(board, piece) {
    let gy = piece.y;
    while (T.board.valid(board, { ...piece, y: gy + 1 })) gy++;
    return gy;
  }

  function drawBoard(board, piece, showGhost) {
    drawGrid();

    // 已堆叠的方块
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const color = board[r][c];
        if (color) drawBlock(ctx, c * CELL, r * CELL, CELL, color, false);
      }
    }

    if (!piece) return;

    // 幽灵投影
    if (showGhost && T.board.valid(board, piece)) {
      const gy = ghostY(board, piece);
      if (gy !== piece.y) {
        const m = piece.matrix;
        for (let r = 0; r < m.length; r++) {
          for (let c = 0; c < m[r].length; c++) {
            if (m[r][c]) {
              drawBlock(ctx, (piece.x + c) * CELL, (gy + r) * CELL, CELL, piece.color, true);
            }
          }
        }
      }
    }

    // 当前方块
    const m = piece.matrix;
    for (let r = 0; r < m.length; r++) {
      for (let c = 0; c < m[r].length; c++) {
        if (m[r][c] && piece.y + r >= 0) {
          drawBlock(ctx, (piece.x + c) * CELL, (piece.y + r) * CELL, CELL, piece.color, false);
        }
      }
    }
  }

  function drawNext(piece) {
    const size = 120; // 预览画布大小
    nextCtx.clearRect(0, 0, size, size);
    if (!piece) return;
    const m = piece.matrix;
    const n = m.length;
    const cellSize = size / 4;
    const offsetX = (4 - n) * cellSize / 2;
    const offsetY = (4 - n) * cellSize / 2;
    for (let r = 0; r < n; r++) {
      for (let c = 0; c < n; c++) {
        if (m[r][c]) {
          drawBlock(nextCtx, offsetX + c * cellSize, offsetY + r * cellSize, cellSize, piece.color, false);
        }
      }
    }
  }

  T.renderer = { init, drawBoard, drawNext };
})(window);
"}

{"filepath": "/mnt/d/project/coding/tetris/js/main.js", "content": "/**
 * main.js —— 游戏主逻辑（模块 5，最后加载）
 * 负责游戏循环、输入处理、计分、等级、暂停与重新开始。
 */
(function (global) {
  'use strict';
  const T = global.Tetris;
  const C = T.constants;

  // DOM 元素
  const scoreEl = document.getElementById('score');
  const levelEl = document.getElementById('level');
  const linesEl = document.getElementById('lines');
  const bestEl = document.getElementById('best');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlay-title');
  const overlayText = document.getElementById('overlay-text');
  const startBtn = document.getElementById('start-btn');

  // 游戏状态
  let board, current, next;
  let score, lines, level, best;
  let running = false, paused = false, over = false;
  let accumulator = 0, lastTime = 0;

  T.renderer.init('board', 'next');
  best = Number(localStorage.getItem(C.BEST_KEY) || 0);
  bestEl.textContent = best;

  function dropInterval() {
    return Math.max(C.MIN_INTERVAL, C.BASE_INTERVAL * Math.pow(C.SPEED_FACTOR, level - 1));
  }

  function updateHud() {
    scoreEl.textContent = score;
    levelEl.textContent = level;
    linesEl.textContent = lines;
    bestEl.textContent = best;
  }

  function spawn() {
    current = next || T.piece.create();
    next = T.piece.create();
    // 出生即碰撞 => 游戏结束
    if (!T.board.valid(board, current)) {
      return false;
    }
    return true;
  }

  function newGame() {
    board = T.board.create();
    score = 0;
    lines = 0;
    level = 1;
    next = T.piece.create();
    accumulator = 0;
    over = false;
    paused = false;
    running = true;
    updateHud();
    if (!spawn()) {
      return gameOver();
    }
    hideOverlay();
    T.renderer.drawBoard(board, current, true);
    T.renderer.drawNext(next);
  }

  function gameOver() {
    running = false;
    over = true;
    if (score > best) {
      best = score;
      localStorage.setItem(C.BEST_KEY, best);
    }
    updateHud();
    showOverlay('游戏结束 💀', `本局得分 <b>${score}</b><br>最高纪录 <b>${best}</b>`);
  }

  function showOverlay(title, html) {
    overlayTitle.textContent = title;
    overlayText.innerHTML = html;
    startBtn.textContent = running ? '继续游戏' : '开始游戏';
    overlay.classList.remove('hidden');
  }
  function hideOverlay() {
    overlay.classList.add('hidden');
  }

  function togglePause() {
    if (!running || over) return;
    paused = !paused;
    if (paused) {
      showOverlay('已暂停', '按 P 或点击按钮继续');
    } else {
      hideOverlay();
      lastTime = performance.now();
    }
  }

  // 固定当前方块，消行并计分，生成下一个
  function lockPiece() {
    T.board.merge(board, current);
    const cleared = T.board.clearLines(board);
    if (cleared > 0) {
      score += C.SCORE_TABLE[cleared] * level;
      lines += cleared;
      level = Math.floor(lines / C.LINES_PER_LEVEL) + 1;
    }
    updateHud();
    if (!spawn()) {
      gameOver();
      return;
    }
    T.renderer.drawNext(next);
  }

  // 下落一步；无法下落则固定
  function stepDown() {
    if (!T.piece.move(current, board, 0, 1)) {
      lockPiece();
    }
  }

  function hardDrop() {
    if (!running || paused || over) return;
    score += T.piece.drop(current, board) * C.HARD_DROP_SCORE;
    updateHud();
    lockPiece();
  }

  // 主循环（requestAnimationFrame，基于时间累积下落）
  function frame(time) {
    if (running && !paused && !over) {
      const dt = lastTime ? time - lastTime : 0;
      accumulator += dt;
      const interval = dropInterval();
      while (accumulator >= interval) {
        stepDown();
        accumulator -= interval;
        if (over) break;
      }
      T.renderer.drawBoard(board, current, true);
    }
    lastTime = time;
    requestAnimationFrame(frame);
  }

  // 键盘输入
  window.addEventListener('keydown', (e) => {
    const key = e.key;
    if (!running) {
      if (key === 'Enter' || key === ' ') {
        e.preventDefault();
        newGame();
      }
      return;
    }
    switch (key) {
      case 'ArrowLeft': case 'a': case 'A':
        e.preventDefault();
        if (!paused && !over) T.piece.move(current, board, -1, 0);
        break;
      case 'ArrowRight': case 'd': case 'D':
        e.preventDefault();
        if (!paused && !over) T.piece.move(current, board, 1, 0);
        break;
      case 'ArrowDown': case 's': case 'S':
        e.preventDefault();
        if (!paused && !over && T.piece.move(current, board, 0, 1)) {
          score += C.SOFT_DROP_SCORE;
          updateHud();
        }
        break;
      case 'ArrowUp': case 'x': case 'X':
        e.preventDefault();
        if (!paused && !over) T.piece.rotate(current, board);
        break;
      case 'z': case 'Z':
        e.preventDefault();
        if (!paused && !over) T.piece.rotateCCW(current, board);
        break;
      case ' ':
        e.preventDefault();
        hardDrop();
        break;
      case 'p': case 'P':
        e.preventDefault();
        togglePause();
        break;
    }
    T.renderer.drawBoard(board, current, true);
  });

  startBtn.addEventListener('click', () => {
    if (!running || over) newGame();
    else togglePause();
  });

  // 初始画面
  board = T.board.create();
  next = T.piece.create();
  T.renderer.drawBoard(board, null, false);
  T.renderer.drawNext(next);
  showOverlay('俄罗斯方块', '← → 移动 · ↓ 软降<br>↑/X 旋转 · 空格硬降<br>按 空格/回车 开始');

  requestAnimationFrame((t) => { lastTime = t; requestAnimationFrame(frame); });
})(window);
"}

